changeSet.sql:
INSERT INTO permissions (name, description)
VALUES ('plugin_devicereset_access', 'Can reset the lock screen PIN of a device');
INSERT INTO userRolePermissions (roleId, permissionId)
SELECT id, currval('permissions_id_seq') FROM userroles WHERE id IN (1, 2);

INSERT INTO permissions (name, description)
VALUES ('plugin_devicereset_wipe', 'Can remotely factory reset a device');
INSERT INTO userRolePermissions (roleId, permissionId)
SELECT id, currval('permissions_id_seq') FROM userroles WHERE id = 1;
